 "use client";

 import Link from "next/link";
 import { useEffect, useState } from "react";
 import { ArrowLeftIcon, CircleAlertIcon, InfoIcon, PencilIcon } from "lucide-react";

 import { ReviewAccess, type ReviewOutcome } from "@/components/review-access";
 import {
   type Plan,
   GroupMembershipPicker,
   roleLabels,
   type Role,
 } from "@/components/group-membership-picker";
 import { type Progress, ReviewProgress } from "@/components/review-progress";
 import { Alert, AlertAction, AlertDescription, AlertTitle } from "@/components/ui/alert";
 import {
   AlertDialog,
   AlertDialogAction,
   AlertDialogCancel,
   AlertDialogContent,
   AlertDialogDescription,
   AlertDialogFooter,
   AlertDialogHeader,
   AlertDialogTitle,
 } from "@/components/ui/alert-dialog";
 import { Button } from "@/components/ui/button";
 import { Field, FieldError, FieldGroup, FieldLabel, FieldSet } from "@/components/ui/field";
 import { Input } from "@/components/ui/input";
 import {
   InputGroup,
   InputGroupAddon,
   InputGroupInput,
   InputGroupText,
 } from "@/components/ui/input-group";
 import { Separator } from "@/components/ui/separator";
 import { Spinner } from "@/components/ui/spinner";
 import { Textarea } from "@/components/ui/textarea";
 import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";

 type SignupRequest = {
   id: string;
   givenName: string;
   familyName: string;
   contactEmail: string;
   phone: string | null;
   connection: string | null;
   workspaceEmail: string;
   workspaceEmailSaved: boolean;
   workspaceEmailTaken: boolean | null;
   workspaceDomain: string | null;
   status: "verified" | "rejection_pending_notification" | Progress["status"];
   rejectionReason: string | null;
   reviewerNotificationState: "pending" | "sent" | "failed";
   createdAt: string;
 };

 type State =
   | { status: "loading" }
   | { status: "unselected" }
   | { status: "ready"; request: SignupRequest; progress?: Progress }
   | { status: "missing" }
   | { status: ReviewOutcome };

 const workspaceEmailCollision =
   "That Workspace email is already in use. Choose a different address.";

 type Errors = Partial<
   Record<
     | "givenName"
     | "familyName"
     | "contactEmail"
     | "workspaceEmail"
     | "phone"
     | "connection"
     | "groups"
     | "reason",
     string
   >
 >;

 async function fetchRequest(id: string): Promise<State> {
   try {
     const response = await fetch(`/api/review/requests/${encodeURIComponent(id)}`, {
       cache: "no-store",
     });
     const result = (await response.json()) as {
       outcome?: ReviewOutcome;
       request?: SignupRequest;
       progress?: Progress;
     };
     if (response.status === 404) return { status: "missing" };
     if (!response.ok || !result.request) return { status: result.outcome ?? "unavailable" };
     return { status: "ready", request: result.request, progress: result.progress };
   } catch {
     return { status: "unavailable" };
   }
 }

 type PlanState =
   | { status: "loading" }
   | { status: "ready"; plan: Plan }
   | { status: ReviewOutcome };
 type PlanResult = Plan & { outcome?: ReviewOutcome; errors?: Errors };

 async function fetchPlan(id: string, init?: RequestInit) {
   try {
     const response = await fetch(`/api/review/requests/${encodeURIComponent(id)}/plan`, {
       cache: "no-store",
       ...init,
     });
     const result = (await response.json()) as PlanResult;
     return { ok: response.ok, result };
   } catch {
     return { ok: false, result: { outcome: "unavailable" } as PlanResult };
   }
 }

 function rolesOf(plan: Plan) {
   return Object.fromEntries(plan.selected.map((group) => [group.groupId, group.role]));
 }

 export function ReviewRequest({ id }: { id?: string }) {
   const [state, setState] = useState<State>({ status: id ? "loading" : "unselected" });
   const [editing, setEditing] = useState(false);
   const [rejecting, setRejecting] = useState(false);
   const [accepting, setAccepting] = useState(false);
   const [acceptError, setAcceptError] = useState<string>();
   const [notificationError, setNotificationError] = useState<string>();
   const [pending, setPending] = useState(false);
   const [errors, setErrors] = useState<Errors>({});
   const [emailEdited, setEmailEdited] = useState(false);
   const [planState, setPlanState] = useState<PlanState>({ status: "loading" });
   const [roles, setRoles] = useState<Record<string, Role>>({});

   useEffect(() => {
     if (!id) return;
     const requestId = id;
     let active = true;
     void fetchRequest(requestId).then((next) => {
       if (active) setState(next);
     });
     return () => {
       active = false;
     };
   }, [id]);

   useEffect(() => {
     if (!id) return;
     let active = true;
     void fetchPlan(id).then(({ ok, result }) => {
       if (!active) return;
       if (ok) {
         setPlanState({ status: "ready", plan: result });
         setRoles(rolesOf(result));
       } else setPlanState({ status: result.outcome ?? "unavailable" });
     });
     return () => {
       active = false;
     };
   }, [id]);

   async function retry() {
     if (!id) return;
     setState({ status: "loading" });
     setState(await fetchRequest(id));
   }

   async function correct(event: React.FormEvent<HTMLFormElement>) {
     event.preventDefault();
     if (!id || state.status !== "ready") return;
     setPending(true);
     setErrors({});
     const values = new FormData(event.currentTarget);
     const { workspaceDomain } = state.request;
     const local = String(values.get("workspaceEmail")).trim();
     const workspaceEmail = local && workspaceDomain ? `${local}@${workspaceDomain}` : local;
     try {
       const response = await fetch(`/api/review/requests/${encodeURIComponent(id)}`, {
         method: "PATCH",
         headers: { "Content-Type": "application/json" },
         body: JSON.stringify({
           givenName: values.get("givenName"),
           familyName: values.get("familyName"),
           contactEmail: values.get("contactEmail"),
           phone: values.get("phone"),
           connection: values.get("connection"),
           // Unchanged proposals are not saved, so a corrected name can still refresh them.
           workspaceEmail:
             workspaceEmail === state.request.workspaceEmail ? undefined : workspaceEmail,
         }),
       });
       const result = (await response.json()) as { errors?: Errors; request?: SignupRequest };
       if (!response.ok) {
         setErrors(result.errors ?? {});
         return;
       }
       if (!result.request) return;
       setState({ status: "ready", request: result.request });
       const plan = await fetchPlan(id, {
         method: "PUT",
         headers: { "Content-Type": "application/json" },
         body: JSON.stringify({
           workspaceEmail: result.request.workspaceEmail,
           groups: Object.entries(roles).map(([groupId, role]) => ({ id: groupId, role })),
         }),
       });
       if (!plan.ok) {
         if (plan.result.errors) setErrors(plan.result.errors);
         else if (plan.result.outcome) setPlanState({ status: plan.result.outcome });
         else setErrors({ groups: "The group assignment could not be saved. Please try again." });
         return;
       }
       setPlanState({ status: "ready", plan: plan.result });
       setRoles(rolesOf(plan.result));
       setState({
         status: "ready",
         request: {
           ...result.request,
           workspaceEmail: plan.result.workspaceEmail,
           workspaceEmailSaved: plan.result.saved,
           workspaceEmailTaken: plan.result.unavailable,
         },
       });
       setEmailEdited(false);
       setEditing(false);
     } catch {
       setErrors({ contactEmail: "The correction could not be saved. Please try again." });
     } finally {
       setPending(false);
     }
   }

   async function accept() {
     if (!id || state.status !== "ready" || planState.status !== "ready") return;
     setPending(true);
     setAcceptError(undefined);
     try {
       // The proposal shown for review becomes the recorded choice.
       if (!state.request.workspaceEmailSaved) {
         const saved = await fetchPlan(id, {
           method: "PUT",
           headers: { "Content-Type": "application/json" },
           body: JSON.stringify({
             workspaceEmail: state.request.workspaceEmail,
             groups: Object.entries(roles).map(([groupId, role]) => ({ id: groupId, role })),
           }),
         });
         if (!saved.ok) {
           setAcceptError(
             saved.result.errors?.workspaceEmail ??
               saved.result.errors?.groups ??
               "The plan could not be saved. Please try again.",
           );
           return;
         }
       }
       const response = await fetch(`/api/review/requests/${encodeURIComponent(id)}/acceptance`, {
         method: "POST",
       });
       const result = (await response.json()) as {
         errors?: Errors;
         error?: string;
         progress?: Progress;
       };
       if (response.ok && result.progress) {
         setState({
           status: "ready",
           request: { ...state.request, status: result.progress.status },
           progress: result.progress,
         });
         setAccepting(false);
         return;
       }
       if (response.status === 409 && result.error) {
         setAccepting(false);
         setState({ status: "missing" });
         return;
       }
       setAcceptError(
         result.errors?.workspaceEmail ??
           result.errors?.groups ??
           "The request could not be accepted. Please try again.",
       );
     } catch {
       setAcceptError("The request could not be accepted. Please try again.");
     } finally {
       setPending(false);
     }
   }

   async function reject(event: React.FormEvent<HTMLFormElement>) {
     event.preventDefault();
     if (!id) return;
     setPending(true);
     setErrors({});
     const reason = new FormData(event.currentTarget).get("reason");
     try {
       const response = await fetch(`/api/review/requests/${encodeURIComponent(id)}/rejection`, {
         method: "POST",
         headers: { "Content-Type": "application/json" },
         body: JSON.stringify({ reason }),
       });
       const result = (await response.json()) as { errors?: Errors; outcome?: string };
       if (response.ok) {
         setState({ status: "missing" });
         return;
       }
       if (result.outcome === "rejection-notification-pending" && state.status === "ready") {
         setState({
           status: "ready",
           request: {
             ...state.request,
             status: "rejection_pending_notification",
             rejectionReason: String(reason),
           },
         });
         setRejecting(false);
         return;
       }
       setErrors(
         result.errors ?? { reason: "The request could not be rejected. Please try again." },
       );
     } catch {
       setErrors({ reason: "The request could not be rejected. Please try again." });
     } finally {
       setPending(false);
     }
   }

   async function retryNotification() {
     if (!id || state.status !== "ready") return;
     setPending(true);
     try {
       const response = await fetch(`/api/review/requests/${encodeURIComponent(id)}/rejection`, {
         method: "POST",
         headers: { "Content-Type": "application/json" },
         body: JSON.stringify({ retry: true }),
       });
       if (response.ok) setState({ status: "missing" });
     } finally {
       setPending(false);
     }
   }

   async function retryReviewerNotification() {
     if (!id || state.status !== "ready") return;
     setPending(true);
     setNotificationError(undefined);
     try {
       const response = await fetch(`/api/review/requests/${encodeURIComponent(id)}/notification`, {
         method: "POST",
       });
       // 409: it was sent meanwhile or the request moved on, so reload the authoritative state.
       if (response.ok || response.status === 409) setState(await fetchRequest(id));
       else setNotificationError("The notification could not be sent. Please try again.");
     } catch {
       setNotificationError("The notification could not be sent. Please try again.");
     } finally {
       setPending(false);
     }
   }

   return (
     <section className="min-h-0 p-4 lg:overflow-y-auto">
       {id && (
         <Button
           className="mb-4 lg:hidden"
           type="button"
           variant="ghost"
           render={<Link href="/review" />}
         >
           <ArrowLeftIcon /> Back to requests
         </Button>
       )}
       {state.status === "loading" && (
         <div className="flex items-center gap-2 text-muted-foreground">
           <Spinner /> Loading request
         </div>
       )}
       {state.status === "unselected" && (
         <p className="text-muted-foreground">Select a signup request to review its details.</p>
       )}
       {state.status === "missing" && (
         <p className="text-muted-foreground">
           This signup request is no longer available for review.
         </p>
       )}
       {state.status === "ready" && state.progress && (
         <ReviewProgress
           name={`${state.request.givenName} ${state.request.familyName}`}
           onProgress={(progress) =>
             setState({ ...state, request: { ...state.request, status: progress.status }, progress })
           }
           progress={state.progress}
           requestId={state.request.id}
         />
       )}
       {state.status === "ready" && !state.progress && (
         <div className="flex flex-col gap-5">
           {state.request.status === "rejection_pending_notification" ? (
             <Alert variant="destructive">
               <CircleAlertIcon />
               <AlertTitle>Rejection notification needs retrying</AlertTitle>
               <AlertDescription>
                 The rejection was recorded, but we could not capture the applicant&apos;s
                 notification.
               </AlertDescription>
               <AlertAction>
                 <Button
                   disabled={pending}
                   onClick={() => void retryNotification()}
                   size="sm"
                   type="button"
                 >
                   {pending && <Spinner data-icon="inline-start" />}
                   Retry notification
                 </Button>
               </AlertAction>
             </Alert>
           ) : (
             <>
               {state.request.status === "verified" &&
                 state.request.reviewerNotificationState !== "sent" && (
                   <Alert>
                     <CircleAlertIcon />
                     <AlertTitle>Reviewer notification not sent</AlertTitle>
                     <AlertDescription>
                       {notificationError ??
                         "Reviewers were not told about this request. It stays in the queue and can be reviewed now."}
                     </AlertDescription>
                     <AlertAction>
                       <Button
                         disabled={pending}
                         onClick={() => void retryReviewerNotification()}
                         size="sm"
                         type="button"
                         variant="outline"
                       >
                         {pending && <Spinner data-icon="inline-start" />}
                         Retry notification
                       </Button>
                     </AlertAction>
                   </Alert>
                 )}
               <form noValidate onSubmit={correct}>
                 <FieldSet className="min-w-0" disabled={pending || !editing}>
                   <FieldGroup className="sm:grid sm:grid-cols-[repeat(2,minmax(0,1fr))]">
                     <Field data-invalid={Boolean(errors.givenName)}>
                       <FieldLabel htmlFor="given-name">Given name</FieldLabel>
                       <Input
                         aria-invalid={Boolean(errors.givenName)}
                         defaultValue={state.request.givenName}
                         id="given-name"
                         name="givenName"
